CREATE SEQUENCE dbo.DispatchNumber
    AS bigint START WITH 700 INCREMENT BY 1;
GO
BEGIN TRANSACTION;
DECLARE @reserved bigint = NEXT VALUE FOR dbo.DispatchNumber;
ROLLBACK TRANSACTION;
SELECT NEXT VALUE FOR dbo.DispatchNumber AS FollowingNumber;

SELECT N'Field kit' AS [item.label],
       12 AS [item.units]
FOR JSON PATH;

SELECT interval_id, avg_duration, count_executions
FROM (VALUES
    (1, CAST(10 AS float), CAST(100 AS bigint)),
    (2, CAST(1000 AS float), CAST(1 AS bigint))
) AS Stats(interval_id, avg_duration, count_executions);
